    @Test public void completionFullDecisionCountIdsAndRetainedOwnershipCorruptionCannotAcknowledge()throws Exception{
        var participant=new SiteEstates(repository);var frozen=decision(1,Recipient.FROZEN);activate(frozen);assertEquals(Outcome.Kind.DONE,participant.settle(frozen).kind());Path path=root.resolve("ownership/completions/"+death+"/1.yml");String original=Files.readString(path);var stamp=SiteDocuments.parse(original);for(String fault:List.of("revision","decision","counts","moved","retained","bad-name")){var changed=SiteDocuments.copy(stamp);switch(fault){case "revision"->changed.put("revision",1.5);case "decision"->changed.put("decision",((String)changed.get("decision")).replace("property=Frozen[]","property=Waiting[]"));case "counts"->changed.put("counts",Map.of("sites",1));case "moved"->changed.put("moved",List.of(UUID.randomUUID().toString()));case "retained"->changed.put("retained",Map.of());case "bad-name"->changed.put("retained",Map.of("bad.yml",CharacterActors.ref(from)));}SiteDocuments.write(path,SiteDocuments.text(changed));assertEquals(Outcome.Kind.BLOCKED,participant.settle(frozen).kind());assertEquals(from,SiteOwnership.director(store.documents().get(id+".yml")));}SiteDocuments.write(path,original);assertEquals(Outcome.Kind.DONE,participant.settle(frozen).kind());
    }

    @Test public void completedZeroBlocksValidPendingReplayOnStartupBeforeAnyOwnershipPublication()throws Exception{
        Files.delete(root.resolve("sites/"+id+".yml"));store.open();var participant=new SiteEstates(repository);var current=decision(1,Recipient.character(to));assertEquals(Outcome.Kind.DONE,participant.settle(current).kind());SiteDocuments.write(root.resolve("sites/"+id+".yml"),SiteDocuments.text(raw()));store.open();String original=store.before(id+".yml");Map<String,Object> header=new LinkedHashMap<>();header.put("death",death.toString());header.put("revision",1);header.put("decision",current.toString());header.put("from",CharacterActors.ref(from));header.put("to",CharacterActors.ref(to));assertThrows(IOException.class,()->store.commit(id+".yml",original,SiteOwnership.transfer(raw(),to),Map.of("kind","estate","estate",header)));assertEquals(original,Files.readString(root.resolve("sites/"+id+".yml")));store.open();assertTrue(store.held(id+".yml"));assertEquals(original,Files.readString(root.resolve("sites/"+id+".yml")));assertEquals(Outcome.Kind.BLOCKED,participant.settle(current).kind());var newer=decision(2,Recipient.character(to));activate(newer);assertEquals(List.of(id.toString()),((Outcome.Done)participant.settle(newer)).movedIds());
    }

    @Test public void corruptHistoricalCompletionOrLaterReceiptBlocksPendingRevisionBeforeSettleOrStartupEffects()throws Exception{
        var participant=new SiteEstates(repository);var frozen=decision(1,Recipient.FROZEN);activate(frozen);assertEquals(Outcome.Kind.DONE,participant.settle(frozen).kind());var newer=decision(2,Recipient.character(to));activate(newer);
        try(var writes=mockStatic(SiteDocuments.class,CALLS_REAL_METHODS)){writes.when(()->SiteDocuments.write(any(Path.class),anyString())).thenAnswer(call->{call.callRealMethod();if(((Path)call.getArgument(0)).toString().contains("ownership/journals"))throw new IOException("crash after valid pending intent");return null;});assertEquals(Outcome.Kind.RETRY,participant.settle(newer).kind());}
        Path pending=store.files("ownership/journals").getFirst(),stamp=root.resolve("ownership/completions/"+death+"/1.yml");String intent=Files.readString(pending),source=Files.readString(root.resolve("sites/"+id+".yml")),completion=Files.readString(stamp);var bad=SiteDocuments.parse(completion);bad.put("counts",Map.of("sites",1));SiteDocuments.write(stamp,SiteDocuments.text(bad));assertEquals(Outcome.Kind.BLOCKED,participant.settle(newer).kind());assertEquals(source,Files.readString(root.resolve("sites/"+id+".yml")));assertEquals(intent,Files.readString(pending));store.open();assertEquals(source,Files.readString(root.resolve("sites/"+id+".yml")));assertEquals(intent,Files.readString(pending));SiteDocuments.write(stamp,completion);
        Path later=root.resolve("ownership/journals/zz-later.yml");var corrupt=SiteDocuments.parse(intent);corrupt.put("id","zz-later");var after=SiteDocuments.parse((String)corrupt.get("after"));after.put("future",Map.of("lost",true));corrupt.put("after",SiteDocuments.text(after));SiteDocuments.write(later,SiteDocuments.text(corrupt));assertEquals(Outcome.Kind.BLOCKED,participant.settle(newer).kind());assertEquals(source,Files.readString(root.resolve("sites/"+id+".yml")));assertEquals(intent,Files.readString(pending));store.open();assertEquals(source,Files.readString(root.resolve("sites/"+id+".yml")));assertEquals(intent,Files.readString(pending));Files.delete(later);store.open();assertEquals(Outcome.Kind.DONE,participant.settle(newer).kind());
    }

    @Test public void changedHistoricalCompletionDecisionCannotDisagreeWithItsRevisionReceipts()throws Exception{
        var participant=new SiteEstates(repository);var original=decision(1,Recipient.character(to));assertEquals(Outcome.Kind.DONE,participant.settle(original).kind());Path stamp=root.resolve("ownership/completions/"+death+"/1.yml");var changed=SiteDocuments.parse(Files.readString(stamp));var wrong=new CharacterRef(UUID.randomUUID(),UUID.randomUUID());changed.put("to",CharacterActors.ref(wrong));changed.put("property",Recipient.character(wrong).toString());changed.put("decision",decision(1,Recipient.character(wrong)).toString());SiteDocuments.write(stamp,SiteDocuments.text(changed));var newer=decision(2,Recipient.WAITING);activate(newer);String source=Files.readString(root.resolve("sites/"+id+".yml"));assertEquals(Outcome.Kind.BLOCKED,participant.settle(newer).kind());assertEquals(source,Files.readString(root.resolve("sites/"+id+".yml")));assertFalse(Files.exists(root.resolve("ownership/completions/"+death+"/2.yml")));
    }
